import React from 'react';

export default function LmsDashboard() {
  const cards = [
    { title: 'Total Students', value: '1,250', color: '#333' },
    { title: 'Total Teachers', value: '45', color: '#333' },
    { title: 'Active Classes', value: '120', color: '#333' },
    { title: 'Inactive Students', value: '25', color: '#d32f2f' }
  ];

  return (
    <div style={{ padding: '30px', backgroundColor: '#f8f9fa', minHeight: '100vh', fontFamily: 'sans-serif' }}>
      
      {/* Top Stats */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '20px', marginBottom: '30px' }}>
        {cards.map((card, index) => (
          <div key={index} style={{ backgroundColor: '#fff', padding: '20px', borderRadius: '12px', boxShadow: '0 4px 6px rgba(0,0,0,0.05)' }}>
            <p style={{ margin: '0', color: '#666', fontSize: '14px' }}>{card.title}</p>
            <h2 style={{ margin: '10px 0 0', color: card.color }}>{card.value}</h2>
          </div>
        ))}
      </div>

      {/* ඉතිරි කොටස් මෙතනට දාමු */}
      <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '20px' }}>
        <div style={{ backgroundColor: '#fff', padding: '20px', borderRadius: '12px', height: '300px' }}>
          <h3>Enrollment Growth & Revenue</h3>
        </div>
        <div style={{ backgroundColor: '#fff', padding: '20px', borderRadius: '12px' }}>
          <h3>Student Status</h3>
        </div>
      </div>

    </div>
  );
}
